    goal: 'Build a list of only the values inside an inclusive range.',
    inputs: 'values is an injected list of 0–20 integers between −100 and 100. lower and upper are injected integers in that range, with lower <= upper.',
    boundaries: 'Include both endpoints, keep input order, and preserve matching duplicates. Empty input or no matches produces []. Equal endpoints select just that value.',
    instructions: 'Leave the matching values in result. Include the stored values themselves, not their positions or a count.',
    starter: 'result = []\n# Keep each value that satisfies both range limits.\n',
