const addedExercises = [...arrayExercises, ...loopExercises];
export const exercises = [...foundationExercises, ...addedExercises].map(entry => ({...entry,...(challengeInfo[entry.id] || {})}));
export const skills = [...coreSkills, ...loopSkills].map(skill => ({
  ...skill,
  exerciseIds: [...new Set([...skill.exerciseIds, ...addedExercises.filter(e => e.kind === 'skill' && e.skillIds[0] === skill.id).map(e => e.id)])],
  challengeIds: exercises.filter(e => e.kind === 'challenge' && e.skillIds.includes(skill.id)).map(e => e.id),
}));

export const exerciseById = Object.fromEntries(exercises.map((exercise) => [exercise.id, exercise]));
export const skillById = Object.fromEntries(skills.map((skill) => [skill.id, skill]));
